def solution():
    # Define variables name and value
    cash_flows = [50, 50, 50, 50, 1050]
    discount_rate = 0.04

    # Do math calculation to get the answer
    present_values = [
        cash_flow / ((1 + discount_rate) ** period)
        for period, cash_flow in enumerate(cash_flows, 1)
    ]
    bond_price = sum(present_values)

    macaulay_duration = sum(
        period * present_value / bond_price
        for period, present_value in enumerate(present_values, 1)
    )

    # Return answer rounded to two decimal places
    return round(macaulay_duration, 2)
